     8  import InteractiveStepSubHeader from '@components/InteractiveStepSubHeader';
     9  import type {InteractiveStepSubHeaderHandle} from '@components/InteractiveStepSubHeader';
    10  import useLocalize from '@hooks/useLocalize';
    11  import useSubStep from '@hooks/useSubStep';
    12  import useThemeStyles from '@hooks/useThemeStyles';
    13  import * as Connections from '@libs/actions/connections/NetSuiteCommands';
    14  import Navigation from '@libs/Navigation/Navigation';
    15  import * as ValidationUtils from '@libs/ValidationUtils';
