    31  const formSteps = [ChooseSegmentTypeStep, CustomSegmentNameStep, CustomSegmentInternalIdStep, CustomSegmentScriptIdStep, MappingStep, ConfirmCustomSegmentList];
    32
    33  function NetSuiteImportAddCustomSegmentPage({policy}: WithPolicyConnectionsProps) {
    34      const policyID = policy?.id ?? '-1';
    35      const styles = useThemeStyles();
    36      const {translate} = useLocalize();
    37      const ref: ForwardedRef<InteractiveStepSubHeaderHandle> = useRef(null);
    38      const formRef = useRef<FormRef | null>(null);
    39
    40      const config = policy?.connections?.netsuite?.options?.config;
    41      const customSegments = useMemo(() => config?.syncOptions?.customSegments ?? [], [config?.syncOptions]);
    42
    43      const handleFinishStep = useCallback(() => {
    44          InteractionManager.runAfterInteractions(() => {
    45              Navigation.goBack(ROUTES.POLICY_ACCOUNTING_NETSUITE_IMPORT_CUSTOM_FIELD_MAPPING.getRoute(policyID, CONST.NETSUITE_CONFIG.IMPORT_CUSTOM_FIELDS.CUSTOM_SEGMENTS));
    46          });
    47      }, [policyID]);
    48
    49      const {
    50          componentToRender: SubStep,
    51          isEditing,
    52          nextScreen,
    53          prevScreen,
    54          screenIndex,
    55          moveTo,
    56          goToTheLastStep,
    57      } = useSubStep<CustomFieldSubStepWithPolicy>({bodyContent: formSteps, startFrom: CONST.NETSUITE_CUSTOM_FIELD_SUBSTEP_INDEXES.CUSTOM_SEGMENTS.SEGMENT_TYPE, onFinished: handleFinishStep});
    58
    59      const handleBackButtonPress = () => {
    60          if (isEditing) {
    61              goToTheLastStep();
    62              return;
    63          }
    64
    65          // Clicking back on the first screen should go back to listing
    66          if (screenIndex === CONST.NETSUITE_CUSTOM_FIELD_SUBSTEP_INDEXES.CUSTOM_SEGMENTS.SEGMENT_TYPE) {
    67              Navigation.goBack(ROUTES.POLICY_ACCOUNTING_NETSUITE_IMPORT_CUSTOM_FIELD_MAPPING.getRoute(policyID, CONST.NETSUITE_CONFIG.IMPORT_CUSTOM_FIELDS.CUSTOM_SEGMENTS));
    68              return;
    69          }
    70          ref.current?.movePrevious();
    71          formRef.current?.resetErrors();
    72          prevScreen();
    73      };
    74
    75      const handleNextScreen = useCallback(() => {
    76          if (isEditing) {
    77              goToTheLastStep();
    78              return;
    79          }
    80          ref.current?.moveNext();
    81          nextScreen();
    82      }, [goToTheLastStep, isEditing, nextScreen]);
    83
    84      const [customSegmentType, setCustomSegmentType] = useState<ValueOf<typeof CONST.NETSUITE_CUSTOM_RECORD_TYPES> | undefined>();
    85
    86      const validate = useCallback(
    87          (values: FormOnyxValues<typeof ONYXKEYS.FORMS.NETSUITE_CUSTOM_SEGMENT_ADD_FORM>): FormInputErrors<typeof ONYXKEYS.FORMS.NETSUITE_CUSTOM_SEGMENT_ADD_FORM> => {
    88              const errors: FormInputErrors<typeof ONYXKEYS.FORMS.NETSUITE_CUSTOM_SEGMENT_ADD_FORM> = {};
    89              const customSegmentRecordType = customSegmentType ?? CONST.NETSUITE_CUSTOM_RECORD_TYPES.CUSTOM_SEGMENT;
    90              switch (screenIndex) {
    91                  case CONST.NETSUITE_CUSTOM_FIELD_SUBSTEP_INDEXES.CUSTOM_SEGMENTS.SEGMENT_NAME:
    92                      if (!ValidationUtils.isRequiredFulfilled(values[INPUT_IDS.SEGMENT_NAME])) {
    93                          errors[INPUT_IDS.SEGMENT_NAME] = translate('workspace.netsuite.import.importCustomFields.requiredFieldError', {
    94                              fieldName: translate(`workspace.netsuite.import.importCustomFields.customSegments.addForm.${customSegmentRecordType}Name`),
    95                          });
    96                      } else if (customSegments.find((customSegment) => customSegment.segmentName.toLowerCase() === values[INPUT_IDS.SEGMENT_NAME].toLowerCase())) {
    97                          const fieldLabel = translate(`workspace.netsuite.import.importCustomFields.customSegments.fields.segmentName`);
    98                          errors[INPUT_IDS.SEGMENT_NAME] = translate('workspace.netsuite.import.importCustomFields.customSegments.errors.uniqueFieldError', {fieldName: fieldLabel});
    99                      }
   100                      return errors;
   101                  case CONST.NETSUITE_CUSTOM_FIELD_SUBSTEP_INDEXES.CUSTOM_SEGMENTS.INTERNAL_ID:
   102                      if (!ValidationUtils.isRequiredFulfilled(values[INPUT_IDS.INTERNAL_ID])) {
   103                          const fieldLabel = translate(`workspace.netsuite.import.importCustomFields.customSegments.fields.internalID`);
   104                          errors[INPUT_IDS.INTERNAL_ID] = translate('workspace.netsuite.import.importCustomFields.requiredFieldError', {fieldName: fieldLabel});
   105                      } else if (customSegments.find((customSegment) => customSegment.internalID.toLowerCase() === values[INPUT_IDS.INTERNAL_ID].toLowerCase())) {
   106                          const fieldLabel = translate(`workspace.netsuite.import.importCustomFields.customSegments.fields.internalID`);
   107                          errors[INPUT_IDS.INTERNAL_ID] = translate('workspace.netsuite.import.importCustomFields.customSegments.errors.uniqueFieldError', {fieldName: fieldLabel});
   108                      }
   109                      return errors;
   110                  case CONST.NETSUITE_CUSTOM_FIELD_SUBSTEP_INDEXES.CUSTOM_SEGMENTS.SCRIPT_ID:
   111                      if (!ValidationUtils.isRequiredFulfilled(values[INPUT_IDS.SCRIPT_ID])) {
   112                          const fieldLabel = translate(
   113                              `workspace.netsuite.import.importCustomFields.customSegments.fields.${
   114                                  customSegmentRecordType === CONST.NETSUITE_CUSTOM_RECORD_TYPES.CUSTOM_SEGMENT ? 'scriptID' : 'customRecordScriptID'
   115                              }`,
   116                          );
   117                          errors[INPUT_IDS.SCRIPT_ID] = translate('workspace.netsuite.import.importCustomFields.requiredFieldError', {fieldName: fieldLabel});
   118                      } else if (customSegments.find((customSegment) => customSegment.scriptID.toLowerCase() === values[INPUT_IDS.SCRIPT_ID].toLowerCase())) {
   119                          const fieldLabel = translate(
   120                              `workspace.netsuite.import.importCustomFields.customSegments.fields.${
   121                                  customSegmentRecordType === CONST.NETSUITE_CUSTOM_RECORD_TYPES.CUSTOM_SEGMENT ? 'scriptID' : 'customRecordScriptID'
   122                              }`,
   123                          );
   124                          errors[INPUT_IDS.SCRIPT_ID] = translate('workspace.netsuite.import.importCustomFields.customSegments.errors.uniqueFieldError', {fieldName: fieldLabel});
   125                      }
   126                      return errors;
   127                  case CONST.NETSUITE_CUSTOM_FIELD_SUBSTEP_INDEXES.CUSTOM_SEGMENTS.MAPPING:
   128                      if (!ValidationUtils.isRequiredFulfilled(values[INPUT_IDS.MAPPING])) {
   129                          errors[INPUT_IDS.MAPPING] = translate('common.error.pleaseSelectOne');
   130                      }
   131                      return errors;
   132                  default:
   133                      return errors;
   134              }
   135          },
   136          [customSegmentType, customSegments, screenIndex, translate],
   137      );
   138
   139      const updateNetSuiteCustomSegments = useCallback(
   140          (formValues: FormOnyxValues<typeof ONYXKEYS.FORMS.NETSUITE_CUSTOM_SEGMENT_ADD_FORM>) => {
   141              const updatedCustomSegments = customSegments.concat([
   142                  {
   143                      segmentName: formValues[INPUT_IDS.SEGMENT_NAME],
   144                      internalID: formValues[INPUT_IDS.INTERNAL_ID],
   145                      scriptID: formValues[INPUT_IDS.SCRIPT_ID],
   146                      mapping: formValues[INPUT_IDS.MAPPING] ?? CONST.INTEGRATION_ENTITY_MAP_TYPES.TAG,
   147                  },
   148              ]);
   149              Connections.updateNetSuiteCustomSegments(
   150                  policyID,
   151                  updatedCustomSegments,
   152                  customSegments,
   153                  `${CONST.NETSUITE_CONFIG.IMPORT_CUSTOM_FIELDS.CUSTOM_SEGMENTS}_${customSegments.length}`,
   154                  CONST.RED_BRICK_ROAD_PENDING_ACTION.ADD,
   155              );
   156              nextScreen();
   157          },
   158          [customSegments, nextScreen, policyID],
   159      );
   160
   161      const renderSubStepContent = useMemo(
   162          () => (
   163              <SubStep
   164                  isEditing={isEditing}
   165                  onNext={handleNextScreen}
   166                  onMove={moveTo}
   167                  screenIndex={screenIndex}
   168                  policyID={policyID}
   169                  policy={policy}
   170                  importCustomField={CONST.NETSUITE_CONFIG.IMPORT_CUSTOM_FIELDS.CUSTOM_SEGMENTS}
   171                  customSegmentType={customSegmentType}
   172                  setCustomSegmentType={setCustomSegmentType}
   173              />
   174          ),
   175          [SubStep, handleNextScreen, isEditing, moveTo, policy, policyID, screenIndex, customSegmentType],
   176      );
   177
   178      const selectionListForm = [CONST.NETSUITE_CUSTOM_FIELD_SUBSTEP_INDEXES.CUSTOM_SEGMENTS.MAPPING as number].includes(screenIndex);
   179      const submitFlexAllowed = [
   180          CONST.NETSUITE_CUSTOM_FIELD_SUBSTEP_INDEXES.CUSTOM_SEGMENTS.SEGMENT_NAME as number,
   181          CONST.NETSUITE_CUSTOM_FIELD_SUBSTEP_INDEXES.CUSTOM_SEGMENTS.INTERNAL_ID as number,
   182          CONST.NETSUITE_CUSTOM_FIELD_SUBSTEP_INDEXES.CUSTOM_SEGMENTS.SCRIPT_ID as number,
   183      ].includes(screenIndex);
   184
   185      return (
   186          <ConnectionLayout
   187              displayName={NetSuiteImportAddCustomSegmentPage.displayName}
   188              headerTitle={`workspace.netsuite.import.importCustomFields.customSegments.${customSegmentType ? `addForm.${customSegmentType}AddTitle` : 'addText'}` as TranslationPaths}
   189              accessVariants={[CONST.POLICY.ACCESS_VARIANTS.ADMIN, CONST.POLICY.ACCESS_VARIANTS.CONTROL]}
   190              policyID={policyID}
   191              featureName={CONST.POLICY.MORE_FEATURES.ARE_CONNECTIONS_ENABLED}
   192              contentContainerStyle={[styles.flex1]}
   193              titleStyle={styles.ph5}
   194              connectionName={CONST.POLICY.CONNECTIONS.NAME.NETSUITE}
   195              onBackButtonPress={handleBackButtonPress}
   196              shouldIncludeSafeAreaPaddingBottom
   197              shouldUseScrollView={false}
   198          >
   199              <View style={[styles.ph5, styles.mb3, styles.mt3, {height: CONST.NETSUITE_FORM_STEPS_HEADER_HEIGHT}]}>
   200                  <InteractiveStepSubHeader
   201                      ref={ref}
   202                      startStepIndex={CONST.NETSUITE_CUSTOM_FIELD_SUBSTEP_INDEXES.CUSTOM_SEGMENTS.SEGMENT_TYPE}
   203                      stepNames={CONST.NETSUITE_CONFIG.NETSUITE_ADD_CUSTOM_SEGMENT_STEP_NAMES}
   204                  />
   205              </View>
   206              <View style={[styles.flexGrow1, styles.mt3]}>
   207                  {screenIndex === CONST.NETSUITE_CUSTOM_FIELD_SUBSTEP_INDEXES.CUSTOM_SEGMENTS.SEGMENT_TYPE ? (
   208                      renderSubStepContent
   209                  ) : (
   210                      <FormProvider
   211                          ref={formRef}
   212                          formID={ONYXKEYS.FORMS.NETSUITE_CUSTOM_SEGMENT_ADD_FORM}
   213                          submitButtonText={screenIndex === formSteps.length - 1 ? translate('common.confirm') : translate('common.next')}
   214                          onSubmit={screenIndex === formSteps.length - 1 ? updateNetSuiteCustomSegments : handleNextScreen}
   215                          validate={validate}
   216                          style={[styles.flexGrow1]}
   217                          submitButtonStyles={[styles.ph5, styles.mb0]}
   218                          shouldUseScrollView={!selectionListForm}
   219                          enabledWhenOffline
   220                          isSubmitDisabled={!!config?.pendingFields?.customSegments}
   221                          submitFlexEnabled={submitFlexAllowed}
   222                          shouldHideFixErrorsAlert={screenIndex === CONST.NETSUITE_CUSTOM_FIELD_SUBSTEP_INDEXES.CUSTOM_SEGMENTS.MAPPING}
   223                      >
   224                          {renderSubStepContent}
   225                      </FormProvider>
   226                  )}
   227              </View>
   228          </ConnectionLayout>
   229      );
   230  }
   231
   232  NetSuiteImportAddCustomSegmentPage.displayName = 'NetSuiteImportAddCustomSegmentPage';
   233
   234  export default withPolicyConnections(NetSuiteImportAddCustomSegmentPage);

