    44      policy,
    45      route: {
    46          params: {importCustomField, valueIndex, fieldName},
    47      },
    48  }: NetSuiteImportCustomFieldViewProps) {
    49      const policyID = policy?.id ?? '-1';
    50      const styles = useThemeStyles();
    51      const {translate} = useLocalize();
    52      const {inputCallbackRef} = useAutoFocusInput();
    53
    54      const config = policy?.connections?.netsuite?.options?.config;
