    56
    57      const customField: CustomField | undefined = allRecords[valueIndex];
    58      const fieldValue = customField?.[fieldName as keyof CustomField] ?? '';
    59
    60      const updateRecord = useCallback(
    61          (formValues: Partial<FormOnyxValues<typeof ONYXKEYS.FORMS.NETSUITE_CUSTOM_FIELD_FORM>>) => {
    62              const newValue = formValues[fieldName as keyof typeof formValues];
    63
    64              if (customField) {
    65                  const updatedRecords = allRecords.map((record, index) => {
    66                      if (index === Number(valueIndex)) {
    67                          return {
    68                              ...record,
    69                              [fieldName]: newValue,
    70                          };
    71                      }
    72                      return record;
    73                  });
    74
    75                  if (PolicyUtils.isNetSuiteCustomSegmentRecord(customField)) {
    76                      updateNetSuiteCustomSegments(
    77                          policyID,
    78                          updatedRecords as NetSuiteCustomSegment[],
    79                          allRecords as NetSuiteCustomSegment[],
    80                          `${importCustomField}_${valueIndex}`,
    81                          CONST.RED_BRICK_ROAD_PENDING_ACTION.UPDATE,
    82                      );
    83                  } else {
    84                      updateNetSuiteCustomLists(
    85                          policyID,
    86                          updatedRecords as NetSuiteCustomList[],
    87                          allRecords as NetSuiteCustomList[],
    88                          `${importCustomField}_${valueIndex}`,
    89                          CONST.RED_BRICK_ROAD_PENDING_ACTION.UPDATE,
    90                      );
    91                  }
