   128                      submitButtonText={translate('common.save')}
   129                      shouldValidateOnBlur
   130                      shouldValidateOnChange
   131                      isSubmitDisabled={!!settingsPendingAction([`${importCustomField}_${valueIndex}`], config?.pendingFields)}
   132                  >
   133                      <InputWrapper
   134                          InputComponent={TextInput}
   135                          inputID={fieldName}
   136                          label={translate(`workspace.netsuite.import.importCustomFields.${importCustomField}.fields.${fieldName}` as TranslationPaths)}
   137                          aria-label={translate(`workspace.netsuite.import.importCustomFields.${importCustomField}.fields.${fieldName}` as TranslationPaths)}
   138                          role={CONST.ROLE.PRESENTATION}
