    38      const containerWidthStyle: ViewStyle = stepNames.length < MIN_AMOUNT_FOR_EXPANDING ? styles.mnw60 : styles.mnw100;
    39
    40      if (stepNames.length < MIN_AMOUNT_OF_STEPS) {
    41          throw new Error(`stepNames list must have at least ${MIN_AMOUNT_OF_STEPS} elements.`);
    42      }
    43
    44      const [currentStep, setCurrentStep] = useState(startStepIndex);
    45      useImperativeHandle(
    46          ref,
    47          () => ({
    48              moveNext: () => {
    49                  setCurrentStep((actualStep) => actualStep + 1);
    50              },
    51              movePrevious: () => {
    52                  setCurrentStep((actualStep) => actualStep - 1);
    53              },
    54          }),
    55          [],
    56      );
    57
    58      const amountOfUnions = stepNames.length - 1;
    59
    60      return (
    61          <View style={[styles.interactiveStepHeaderContainer, containerWidthStyle]}>
    62              {stepNames.map((stepName, index) => {
    63                  const isCompletedStep = currentStep > index;
    64                  const isLockedStep = currentStep < index;
    65                  const isLockedLine = currentStep < index + 1;
    66                  const hasUnion = index < amountOfUnions;
    67
    68                  const moveToStep = () => {
    69                      if (isLockedStep || !onStepSelected) {
    70                          return;
    71                      }
    72                      setCurrentStep(index);
    73                      const step = stepNames.at(index);
    74                      if (step) {
    75                          onStepSelected(step);
    76                      }
    77                  };
    78
    79                  return (
    80                      <View
    81                          style={[styles.interactiveStepHeaderStepContainer, hasUnion && styles.flex1]}
    82                          key={stepName}
    83                      >
    84                          <PressableWithFeedback
    85                              style={[
    86                                  styles.interactiveStepHeaderStepButton,
    87                                  isLockedStep && styles.interactiveStepHeaderLockedStepButton,
    88                                  isCompletedStep && styles.interactiveStepHeaderCompletedStepButton,
    89                                  !onStepSelected && styles.cursorDefault,
    90                              ]}
    91                              disabled={isLockedStep || !onStepSelected}
    92                              onPress={moveToStep}
    93                              accessible
    94                              accessibilityLabel={stepName[index]}
    95                              role={CONST.ROLE.BUTTON}
    96                          >
    97                              {isCompletedStep ? (
    98                                  <Icon
    99                                      src={Expensicons.Checkmark}
   100                                      width={variables.iconSizeNormal}
   101                                      height={variables.iconSizeNormal}
   102                                      fill={colors.white}
   103                                  />
   104                              ) : (
   105                                  <Text style={[styles.interactiveStepHeaderStepText, isLockedStep && styles.textSupporting]}>{index + 1}</Text>
   106                              )}
   107                          </PressableWithFeedback>
   108                          {hasUnion ? <View style={[styles.interactiveStepHeaderStepLine, isLockedLine && styles.interactiveStepHeaderLockedStepLine]} /> : null}
   109                      </View>
   110                  );
   111              })}
   112          </View>
   113      );
   114  }
   115
   116  InteractiveStepSubHeader.displayName = 'InteractiveStepSubHeader';
   117
   118  export type {InteractiveStepSubHeaderProps, InteractiveStepSubHeaderHandle};
   119
   120  export default forwardRef(InteractiveStepSubHeader);
